def normalise(values):
    total = sum(values)
    if not total:
        return list(values)

    return [x / total for x in values]


def report(rows):
    names = [row.name for row in rows]
    weights = normalise([row.weight for row in rows])
    for name, weight in zip(names, weights):
        print(name, weight)


if __name__ == '__main__':
    report(load())
